function solve(a,b){let c=a;let d=b;if(c.length>d.length){[c,d]=[d,c];}const e=c.length;const f=d.length;if(e+f===0){throw new RangeError('Both arrays are empty');}const g=Math.floor((e+f+1)/2);let r=0;let h=e;while(r<=h){const a=Math.floor((r+h)/2);const b=g-a;const i=a===0?-Infinity:c[a-1];const j=a===e?Infinity:c[a];const k=b===0?-Infinity:d[b-1];const l=b===f?Infinity:d[b];if(i<=l&&k<=j){const a=Math.max(i,k);if((e+f)%2===1){return a;}const b=Math.min(j,l);return a/2+b/2;}if(i>l){h=a-1;}else{r=a+1;}}throw new RangeError('Inputs must be sorted in ascending order');}
